	skel := &stateSkel{}
	ready, err := skel.isDaemonSetReady(toUnstructuredDaemonSet(t, staleDaemonSet), logr.Discard())
	require.NoError(t, err)
	require.False(t, ready, "stale-generation status must not mark the current rollout ready")
